export function regionalDestinations(world){
 const places=world.coast.meta.places,roads=world.network.roads;
 function nearestRoad(name,anchor){let best=null;for(const r of roads.filter(r=>r.name===name&&!['footway','path','cycleway','steps','service'].includes(r.type)))for(let i=1;i<r.p.length;i++){const a=r.p[i-1],b=r.p[i],dx=b.x-a.x,dz=b.y-a.y,t=Math.max(0,Math.min(1,((anchor.x-a.x)*dx+(anchor.z-a.y)*dz)/(dx*dx+dz*dz||1))),x=a.x+dx*t,z=a.y+dz*t,d=Math.hypot(x-anchor.x,z-anchor.z);if(!best||d<best.d)best={x,z,d,width:r.width||7,yaw:Math.atan2(-dx,-dz)}}return best}
 const lower=places.find(p=>p.name==='Lower Hutt')||{x:-3166,z:-5557},petone=places.find(p=>p.name==='Petone')||{x:-5436,z:-4230},eastbourne=places.find(p=>p.name==='Eastbourne')||{x:-3973,z:3175};
 const result=new Map();for(const [id,name,road,anchor,yaw]of [['lowerhutt','Lower Hutt','High Street',lower,0],['petone','Petone waterfront','The Esplanade',petone,Math.PI],['daysbay','Days Bay','Marine Drive',{x:-3280,z:2000},Math.PI/2],['eastbourne','Eastbourne','Marine Parade',eastbourne,Math.PI/2]]){
  const hit=nearestRoad(road,anchor)||nearestRoad(id==='eastbourne'?'Muritai Road':'Marine Drive',anchor);if(!hit)continue;let point=hit;
  // Stand on the verge rather than in a traffic lane; prefer the coastal side.
  for(const radius of [hit.width/2+.55,3,0]){const x=id==='lowerhutt'?hit.x+Math.cos(hit.yaw)*radius:hit.x-Math.sin(yaw)*radius,z=id==='lowerhutt'?hit.z-Math.sin(hit.yaw)*radius:hit.z-Math.cos(yaw)*radius;if(world.coast.isLand(x,z)&&!world.hydro.channel(x,z)){point={x,z};break}}
  if(id!=='lowerhutt'){
   let shore=null;for(const ring of world.coast.meta.beaches||[]){const centre={x:ring.reduce((s,p)=>s+p[0],0)/ring.length,z:ring.reduce((s,p)=>s+p[1],0)/ring.length},samples=[centre];for(let i=1;i<ring.length;i++)samples.push({x:(ring[i-1][0]+ring[i][0])/2,z:(ring[i-1][1]+ring[i][1])/2});for(const p of samples){const d=Math.hypot(p.x-anchor.x,p.z-anchor.z);if(d<850&&(!shore||d<shore.d)&&world.coast.isLand(p.x,p.z)&&!world.hydro.channel(p.x,p.z))shore={...p,d}}}if(shore)point=shore;
  }
  result.set(id,{name,x:point.x,z:point.z,yaw:id==='lowerhutt'?hit.yaw:yaw});
 }
 // Anchors are on mapped entrance roads and tracks, not invented routes.
 for(const [id,name,road,anchor]of [['upperhutt','Upper Hutt · Main Street','Main Street',{x:10838,z:-15076}],['silverstream','Silverstream · Kiln Street','Kiln Street',{x:5700,z:-12100}],['trentham','Trentham · Fergusson Drive','Fergusson Drive',{x:8300,z:-14200}],['totara-park','Tōtara Park · California Drive','California Drive',{x:12400,z:-16900}]]){const hit=nearestRoad(road,anchor);if(hit&&hit.d<2000){const offset=hit.width/2+.8;result.set(id,{name,x:hit.x+Math.cos(hit.yaw)*offset,z:hit.z-Math.sin(hit.yaw)*offset,yaw:hit.yaw,pitch:-.05})}}
 const roofView=result.get('trentham');if(roofView)result.set('upper-roofs',{name:'Upper Hutt · Roof view',x:roofView.x+90,z:roofView.z+80,yaw:Math.atan2(90,80),pitch:-.55,drone:true});
 for(const [id,name,road,anchor]of [
  ['forest-park','Wainuiomata Regional Park · Hine Road','Hine Road',{x:2031,z:1609}],
  ['reservoir-trails','Forest park · Reservoir Road trails','Reservoir Road',{x:3634,z:799}],
  ['catchpool','Remutaka Forest Park · Catchpool Valley','Catchpool Loop',{x:-1463,z:9511}],
  ['wainui-coast','Wainuiomata coast · Coast Road beach','Coast Road',{x:-4467,z:16902}],
  ['dowse-overbridge','Dowse Drive overbridge','Dowse Drive',{x:-5082,z:-5229}]
 ]){let best=null;for(const r of roads.filter(r=>r.name===road))for(const p of r.p){const d=Math.hypot(p.x-anchor.x,p.y-anchor.z);if(!best||d<best.d)best={x:p.x,z:p.y,d}}if(best)result.set(id,{name,x:best.x,z:best.z-(id==='dowse-overbridge'?100:0),yaw:id==='wainui-coast'||id==='dowse-overbridge'?Math.PI:0,...(id==='dowse-overbridge'?{drone:true}:{})})}
 for(const [id,name,road,anchor]of [['hill-road-review','Wainuiomata Hill Road · Road view','Wainuiomata Hill Road',{x:-1741,z:-1247}],['mawson-review','Mawson Street · Road view','Mawson Street',{x:-1888,z:-3815}]]){const hit=nearestRoad(road,anchor);if(hit){const offset=hit.width/2+.65;result.set(id,{name,x:hit.x+Math.cos(hit.yaw)*offset,z:hit.z-Math.sin(hit.yaw)*offset,yaw:hit.yaw,pitch:-.10})}}
 const trafficRules=world.traffic?.rules;if(trafficRules){for(const post of (world.intersections?.plans||[]).filter(p=>p.kind!=='signal').sort((a,b)=>Math.hypot(a.x,a.z)-Math.hypot(b.x,b.z))){if(trafficRules.crossings.some(c=>Math.hypot(c.x-post.x,c.z-post.z)<15))continue;const x=post.x-post.dx*13,z=post.z-post.dz*13,clear=[0,2,4,6].every(t=>[-1,1].every(side=>[-1,1].every(end=>world.freeSpace?.(x+post.dx*(t+end*2.5)+post.dz*side,z+post.dz*(t+end*2.5)-post.dx*side))));if(clear){result.set('sign-crash',{name:'Breakaway sign · Drive',x,z,yaw:post.yaw,drive:true});break}}const signalPlans=(world.intersections?.plans||[]).filter(p=>p.kind==='signal').sort((a,b)=>Math.hypot(a.x+3166,a.z+5557)-Math.hypot(b.x+3166,b.z+5557));for(const p of signalPlans){const x=p.x-p.dx*14,z=p.z-p.dz*14;if(world.free(x,z)){result.set('traffic-signals',{name:'Traffic lights · '+(p.edge.r.name||'Hutt Valley'),x,z,yaw:p.yaw,pitch:.02});break}}const signals=[...trafficRules.junctions.values()].filter(j=>j.control?.tags.highway==='traffic_signals').sort((a,b)=>Math.hypot(a.group.x+3166,a.group.z+5557)-Math.hypot(b.group.x+3166,b.group.z+5557));for(const j of result.has('traffic-signals')?[]:signals){const e=j.entries[0],dx=(e.to.x-e.from.x)/e.length,dz=(e.to.y-e.from.y)/e.length,back=j.group.radius+15,x=e.to.x-dx*back+dz*(e.r.width/2+.8),z=e.to.y-dz*back-dx*(e.r.width/2+.8);if(world.free(x,z)){result.set('traffic-signals',{name:'Traffic lights · '+(e.r.name||'Hutt Valley'),x,z,yaw:Math.atan2(-dx,-dz),pitch:0});break}}for(const c of [...trafficRules.crossings].filter(c=>c.kind==='zebra').sort((a,b)=>Math.hypot(a.x,a.z)-Math.hypot(b.x,b.z))){const x=c.x-c.dx*12+c.dz*(c.width/2+.8),z=c.z-c.dz*12-c.dx*(c.width/2+.8);if(world.free(x,z)){const hit=world.network.at(c.x,c.z);result.set('pedestrian-crossing',{name:'Pedestrian crossing · '+(hit?.r.name||'Wainuiomata'),x,z,yaw:Math.atan2(-c.dx,-c.dz),pitch:-.05});break}}}
 const sign=world.furniture?.plan.signs.find(s=>s.name==='Short Street'&&s.pole.signs.some(s=>s.name==='Bledisloe Crescent'));if(sign){const hit=nearestRoad('Short Street',{x:431,z:637});if(hit){const offset=hit.width/2+.65,x=hit.x+Math.cos(hit.yaw)*offset,z=hit.z-Math.sin(hit.yaw)*offset;result.set('short-street',{name:'Short Street · Bledisloe Crescent',x,z,yaw:Math.atan2(x-sign.pole.x,z-sign.pole.z)})}}
 const river=world.hydro.rivers?.find(r=>r.name==='Wainuiomata River');if(river){const street=nearestRoad('Stanley Street',{x:330,z:1140});if(street){const x=street.x+Math.cos(street.yaw)*(street.width/2+.65),z=street.z-Math.sin(street.yaw)*(street.width/2+.65);result.set('river-road',{name:'Stanley Street · Riverside',x,z,yaw:Math.atan2(x-300.56,z-1169.49),pitch:-.10})}const points=river.p.filter((p,i)=>i%5===0).sort((a,b)=>Math.hypot(a.x-150,a.z-1450)-Math.hypot(b.x-150,b.z-1450));outer:for(const p of points){const water=world.water?.at(p.x,p.z);if(!water||water.depth<1.5)continue;for(const side of [-1,1]){const x=p.x+p.nx*(p.width/2+5)*side,z=p.z+p.nz*(p.width/2+5)*side;if(!world.free(x,z))continue;const yaw=Math.atan2(x-p.x,z-p.z);result.set('river-swim',{name:'Wainuiomata River · Swim',x:p.x,z:p.z,yaw,swim:true,pitch:-.04});result.set('river-bank',{name:'Wainuiomata River · Bank',x,z,yaw,pitch:-.18});const dx=p.x+p.nx*(p.width/2+15)*side,dz=p.z+p.nz*(p.width/2+15)*side,clear=[-1,1].every(a=>[-1,1].every(b=>world.free(dx+p.nx*a*2.6+p.nz*b,dz+p.nz*a*2.6-p.nx*b)));result.set('river-drive',{name:'Wainuiomata River · Drive',x:clear?dx:x,z:clear?dz:z,yaw,drive:true});break outer}}}
 return result;
}
